// n8n Code node — "Download House ZIP"
// -----------------------------------------------------------------------------
// Workaround for ScrapeUnblocker's 403 on binary files: fetch the .zip using
// n8n's BUILT-IN HTTP helper (this.helpers.httpRequest) instead of the HTTP
// Request node, and hand back real binary for the Compression node.
//
// Honest note: this is still an HTTP GET under the hood — a file cannot be
// downloaded without one — but it lives entirely inside a Code node, so no
// HTTP Request node appears on the canvas.
//
// MODE: Run Once for All Items   |   LANGUAGE: JavaScript
// Place BETWEEN "Extract House ZIP URL" and "Decompress House ZIP".
// -----------------------------------------------------------------------------

const results = [];

for (const item of $input.all()) {
  const zipUrl = item.json.zipUrl;
  if (!zipUrl) continue;

  // Fetch the archive as raw bytes (arraybuffer -> Buffer).
  const raw = await this.helpers.httpRequest({
    method: 'GET',
    url: zipUrl,
    encoding: 'arraybuffer',
    headers: { 'User-Agent': 'Mozilla/5.0 ProfitableMedia congress-tracker' },
    returnFullResponse: false,
  });

  const buffer = Buffer.from(raw);

  // Sanity check: a real ZIP starts with the bytes "PK".
  if (!(buffer.length > 3 && buffer[0] === 0x50 && buffer[1] === 0x4b)) {
    throw new Error(
      'Downloaded data is not a valid ZIP (no PK header) for ' + zipUrl +
      '. The server may have returned an error page instead of the file.'
    );
  }

  const fileName = (zipUrl.match(/([^/]+\.zip)/) || [])[1] || 'archive.zip';

  // prepareBinaryData is filesystem-binary-mode safe.
  const binaryData = await this.helpers.prepareBinaryData(
    buffer,
    fileName,
    'application/zip'
  );

  results.push({ json: { zipUrl, bytes: buffer.length }, binary: { data: binaryData } });
}

return results;

// n8n Code node — "Fetch EDGAR Feed"
// -----------------------------------------------------------------------------
// SEC EDGAR returns 403 for any request without a declared User-Agent (their
// fair-access policy). ScrapeUnblocker can't set a custom UA, which is why it
// 403s. We fetch here with n8n's built-in HTTP helper and a compliant UA.
//
// >>> EDIT the contact email in USER_AGENT to your real address — SEC requires it.
//
// MODE: Run Once for All Items   |   Wire: Every 45 Min -> this node -> Parse EDGAR RSS
// -----------------------------------------------------------------------------

const FEED_URL =
  'https://www.sec.gov/cgi-bin/browse-edgar?action=getcurrent&type=4&company=&dateb=&owner=include&count=40&output=atom';

const USER_AGENT = 'ProfitableMedia congress-tracker user@example.com';

const body = await this.helpers.httpRequest({
  method: 'GET',
  url: FEED_URL,
  headers: {
    'User-Agent': USER_AGENT,
    'Accept': 'application/atom+xml,application/xml,text/xml',
    'Accept-Encoding': 'gzip, deflate',
  },
  json: false,               // return the raw XML string, not parsed JSON
  returnFullResponse: false,
});

return [{ json: { data: String(body) } }];

// Enrich each EDGAR filing with real trade data from its Form 4 ownership XML.
// amountRange: real $ value for open-market Buy/Sell (shares × price); for grants /
// option exercises (no price) it falls back to the share quantity so the field is
// never empty. Identical option-exercise legs (same qty listed twice) are deduped.
// MODE: Run Once for All Items.  >>> put your real contact email in UA (SEC requirement).
const UA='ProfitableMedia congress-tracker user@example.com';
const CODE={P:'Buy (open market)',S:'Sell (open market)',A:'Grant/Award',D:'Disposition to issuer',F:'Tax withholding',G:'Gift',M:'Option exercise',X:'Option exercise',C:'Conversion',J:'Other'};
function g(blk,tag){const m=blk.match(new RegExp('<'+tag+'>\\s*(?:<value>)?\\s*([^<]*?)\\s*(?:</value>)?\\s*</'+tag+'>'));return m?m[1].trim():'';}
const out=[];
for(const item of $input.all()){
  const j={...item.json};
  try{
    const base=String(j.filingUrl||'').replace(/[^/]*$/,'');
    const dir=await this.helpers.httpRequest({method:'GET',url:base+'index.json',headers:{'User-Agent':UA},json:true});
    const files=((dir.directory&&dir.directory.item)||[]).map(f=>f.name);
    const xmlName=files.find(n=>/\.xml$/i.test(n)&&!/^R\d+\.xml$/i.test(n)&&!/metalinks/i.test(n));
    if(xmlName){
      const xml=String(await this.helpers.httpRequest({method:'GET',url:base+xmlName,headers:{'User-Agent':UA},json:false}));
      const ticker=(xml.match(/<issuerTradingSymbol>([^<]*)/)||[])[1]||'';
      let txns=[];
      for(const b of (xml.match(/<(?:nonDerivative|derivative)Transaction>[\s\S]*?<\/(?:nonDerivative|derivative)Transaction>/g)||[])){
        const code=g(b,'transactionCode'), shares=parseFloat(g(b,'transactionShares'))||0, price=parseFloat(g(b,'transactionPricePerShare'))||0, date=g(b,'transactionDate');
        txns.push({ticker,label:CODE[code]||('Code '+code),shares,price,value:+(shares*price).toFixed(2),date});
      }
      // dedupe identical legs (option exercise lists the same qty twice)
      const seen=new Set(),uniq=[];
      for(const t of txns){const k=t.label+'|'+t.shares+'|'+t.price+'|'+t.date; if(seen.has(k))continue; seen.add(k); uniq.push(t);}
      if(uniq.length){
        const dollar=uniq.reduce((s,t)=>s+t.value,0);
        const sharesTot=uniq.reduce((s,t)=>s+t.shares,0);
        j.ticker=ticker;
        j.transactionType=[...new Set(uniq.map(t=>t.label))].join(', ');
        j.amountRange = dollar>0 ? ('$'+dollar.toLocaleString()) : (sharesTot>0 ? (sharesTot.toLocaleString()+' shares') : '');
        j.transactionDate=uniq[0].date||j.transactionDate;
        j.details=uniq.map(t=>t.ticker+' '+t.label+' '+t.shares+' sh'+(t.price?(' @ $'+t.price):'')+(t.value?(' = $'+t.value.toLocaleString()):'')+' ('+t.date+')').join('\n');
      }
    }
  }catch(e){ j.enrichError=String(e.message||e); }
  out.push({json:j});
}
return out;

// Download each House PTR PDF as binary (via n8n HTTP helper) for text extraction.
const UA='Mozilla/5.0 ProfitableMedia congress-tracker';
const out=[];
for(const item of $input.all()){
  const j={...item.json};
  try{
    const raw=await this.helpers.httpRequest({method:'GET',url:j.filingUrl,headers:{'User-Agent':UA},encoding:'arraybuffer',returnFullResponse:false});
    const bin=await this.helpers.prepareBinaryData(Buffer.from(raw),(j.docId||'ptr')+'.pdf','application/pdf');
    out.push({json:j,binary:{data:bin}});
  }catch(e){ j.enrichError=String(e.message||e); out.push({json:j}); }
}
return out;

// Parse House PTR — SELF-SUFFICIENT.
// The Extract-from-File node replaces item.json with the PDF output (numpages/info/text/version),
// wiping the upstream House fields. So we re-derive EVERYTHING from the PDF text itself:
// filingId, member, state, filingUrl, plus the trade rows. Best-effort; scanned PDFs yield nothing.
// MODE: Run Once for All Items.

function toISO(d){const m=String(d).match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);return m?`${m[3]}-${m[1].padStart(2,'0')}-${m[2].padStart(2,'0')}`:'';}

const ROW=/\b([PSE])\b\s*\(?(?:partial|full)?\)?\s+(\d{2}\/\d{2}\/\d{4})\s+(\d{2}\/\d{2}\/\d{4})\s+(\$[\d,]+(?:\s*-\s*\$[\d,]+)?(?:\s*\+)?)/;
const TICK=/\((?:Ticker:\s*)?([A-Z][A-Z0-9.\-]{0,5})\)/;
const BOUND=/:\s*New\b|Notification|Filing ID|Amount Cap|\u0000/;
const TYPE={P:'Buy',S:'Sell',E:'Exchange'};

const out=[];
for(const item of $input.all()){
  const j={...item.json};
  const text=String(j.pdfText||j.text||'');

  // --- recover header fields from the PDF text ---
  const fid=(text.match(/Filing ID #(\d+)/)||[])[1]||'';
  const name=((text.match(/Name:\s*(.+)/)||[])[1]||'').trim();
  const sd=(text.match(/State\/District:\s*([A-Z]{2})(\d+)/)||[]);
  const signed=(text.match(/Digitally Signed:[^,]*,\s*(\d{2}\/\d{2}\/\d{4})/)||[])[1]||'';

  // --- parse the transaction rows ---
  const lines=text.split(/\r?\n/);
  const txns=[];
  for(let i=0;i<lines.length;i++){
    const m=lines[i].match(ROW); if(!m) continue;
    let tk=(lines[i].match(TICK)||[])[1]||'';
    if(!tk){ for(let k=i-1;k>=Math.max(0,i-4);k--){ if(BOUND.test(lines[k])||ROW.test(lines[k])) break; const t=(lines[k].match(TICK)||[])[1]; if(t){tk=t;break;} } }
    txns.push({ticker:tk,type:TYPE[m[1]]||m[1],date:toISO(m[2]),amount:m[4].replace(/\s+/g,' ').trim()});
  }

  const year=(signed.match(/\/(\d{4})/)||[])[1] || (txns[0]&&txns[0].date.slice(0,4)) || String(new Date().getFullYear());

  // --- rebuild the full standard schema ---
  const rec={
    filingId: fid ? ('HOUSE-'+fid) : '',
    source: 'House',
    memberName: name,
    party: '',
    state: sd[1]||'',
    district: sd[2]||'',
    ticker: [...new Set(txns.map(t=>t.ticker).filter(Boolean))].join(', '),
    transactionType: [...new Set(txns.map(t=>t.type))].join(', '),
    amountRange: [...new Set(txns.map(t=>t.amount))].join('; '),
    transactionDate: txns[0] ? txns[0].date : '',
    filingDate: toISO(signed),
    filingUrl: fid ? `https://disclosures-clerk.house.gov/public_disc/ptr-pdfs/${year}/${fid}.pdf` : (j.filingUrl||''),
    details: txns.map(t=>(t.ticker||'?')+' '+t.type+' '+t.amount+' ('+t.date+')').join('\n'),
    docId: fid,
    alertedAt: j.alertedAt || new Date().toISOString()
  };
  // drop scanned/empty PDFs (no filing id parsed)
  if(!rec.filingId) continue;
  out.push({json:rec});
}
return out;

// Extract the current-year House disclosure ZIP URL from the landing-page HTML.
function getContent(json){
  if(typeof json==='string')return json;
  if(Array.isArray(json))return json.find(v=>typeof v==='string'&&v.includes('<'))||'';
  for(const k of ['data','body','html','content','result','response','text']){
    const v=json&&json[k];
    if(typeof v==='string'&&v.includes('<'))return v;
    if(Array.isArray(v)){const s=v.find(x=>typeof x==='string'&&x.includes('<'));if(s)return s;}
  }
  for(const v of Object.values(json||{}))if(typeof v==='string'&&v.includes('<'))return v;
  return '';
}
const BASE='https://disclosures-clerk.house.gov';
const out=[];
for(const item of $input.all()){
  const html=getContent(item.json); if(!html) continue;
  const urls=[...html.matchAll(/href="([^"]+?\.zip[^"]*)"/gi)]
    .map(m=>m[1].startsWith('http')?m[1]:BASE+(m[1].startsWith('/')?'':'/')+m[1]);
  const uniq=[...new Set(urls)]; if(!uniq.length) continue;
  const byYear=uniq.map(u=>({url:u,year:parseInt((u.match(/(\d{4})FD\.zip/)||[])[1]||0,10)}))
                   .filter(x=>x.year).sort((a,b)=>b.year-a.year);
  const latest=byYear[0];
  out.push({ json:{ zipUrl: latest?latest.url:uniq[0], year: latest?latest.year:null, allZipUrls: uniq } });
}
return out;

// Parse House Periodic Transaction Reports (FilingType "P") from the decompressed
// 20xxFD archive. Reads the binary file emitted by the Compression node using
// this.helpers.getBinaryDataBuffer — works in BOTH inline and filesystem binary
// modes. Handles the .xml OR the tab-delimited .txt. Tested parse logic: 274 P filings.
//
// MODE: Run Once for All Items   |   Wire: Decompress House ZIP -> this node.

function decodeEntities(s){return String(s).replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#0?39;/g,"'").replace(/&nbsp;/g,' ');}
function getContent(json){ // accept only XML/TSV-looking text (never the zipUrl)
  const ok=v=>typeof v==='string'&&(v.includes('<')||v.includes('\t'));
  if(ok(json))return json;
  if(Array.isArray(json)){const s=json.find(ok);if(s)return s;}
  for(const k of ['data','body','content','result','response','xml','text','fileContent']){
    const v=json&&json[k]; if(ok(v))return v;
    if(Array.isArray(v)){const s=v.find(ok);if(s)return s;}
  }
  for(const v of Object.values(json||{}))if(ok(v))return v;
  return '';
}
function toISO(d){const m=String(d).match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);return m?`${m[3]}-${m[1].padStart(2,'0')}-${m[2].padStart(2,'0')}`:String(d||'').trim();}
function rec(f){return { json:{
  filingId:'HOUSE-'+f.docId, source:'House',
  memberName:[f.prefix,f.first,f.last,f.suffix].filter(Boolean).join(' ').trim(),
  party:'', state:(f.stateDst||'').slice(0,2),
  transactionType:'', amountRange:'', transactionDate:'',
  filingDate:toISO(f.filingDate),
  filingUrl:`https://disclosures-clerk.house.gov/public_disc/ptr-pdfs/${f.year||new Date().getFullYear()}/${f.docId}.pdf`,
  district:(f.stateDst||'').slice(2), docId:f.docId
}};}
function parseXml(c){const out=[];
  for(const blk of (c.match(/<Member>([\s\S]*?)<\/Member>/g)||[])){
    const pick=t=>{const m=blk.match(new RegExp('<'+t+'>([\\s\\S]*?)<\\/'+t+'>'));return m?decodeEntities(m[1]).trim():'';};
    if(pick('FilingType')!=='P')continue; const docId=pick('DocID'); if(!docId)continue;
    out.push(rec({prefix:pick('Prefix'),first:pick('First'),last:pick('Last'),suffix:pick('Suffix'),stateDst:pick('StateDst'),year:pick('Year'),filingDate:pick('FilingDate'),docId}));
  } return out;}
function parseTsv(c){const out=[]; const lines=c.split(/\r?\n/).filter(l=>l.trim()); if(!lines.length)return out;
  const h=lines[0].split('\t').map(x=>x.trim()); const ix=n=>h.indexOf(n);
  const I={p:ix('Prefix'),l:ix('Last'),f:ix('First'),s:ix('Suffix'),ft:ix('FilingType'),sd:ix('StateDst'),y:ix('Year'),d:ix('FilingDate'),doc:ix('DocID')};
  if(I.ft<0||I.doc<0)return out;
  for(let i=1;i<lines.length;i++){const c2=lines[i].split('\t'); if((c2[I.ft]||'').trim()!=='P')continue;
    const docId=(c2[I.doc]||'').trim(); if(!docId)continue;
    out.push(rec({prefix:(c2[I.p]||'').trim(),first:(c2[I.f]||'').trim(),last:(c2[I.l]||'').trim(),suffix:(c2[I.s]||'').trim(),stateDst:(c2[I.sd]||'').trim(),year:(c2[I.y]||'').trim(),filingDate:(c2[I.d]||'').trim(),docId}));
  } return out;}

const out=[];
const items=$input.all();
for(let i=0;i<items.length;i++){
  const item=items[i];
  let content=getContent(item.json);          // path 1: text already in json (Extract-from-File)

  if(!content && item.binary){                 // path 2: decompressed binary (filesystem-safe)
    const keys=Object.keys(item.binary);
    const pick=keys.find(k=>/\.xml$/i.test(item.binary[k].fileName||k))
            || keys.find(k=>/\.txt$/i.test(item.binary[k].fileName||k))
            || keys[0];
    if(pick){
      const buf=await this.helpers.getBinaryDataBuffer(i,pick);
      content=buf.toString('utf8');
    }
  }
  if(!content) continue;
  out.push(...(/<Member>/.test(content)?parseXml(content):parseTsv(content)));
}
return out;

// Parse the SEC EDGAR Form 4 Atom feed (from the ScrapeUnblocker output) and
// map straight to the standard schema. Keeps only Form 4s by the Reporting person
// (the insider who traded); the duplicate Issuer/company row is dropped.
// Auto-detects the content field. Tested against the live feed.
function decodeEntities(s){return String(s).replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#0?39;/g,"'").replace(/&nbsp;/g,' ');}
function getContent(json){
  if(typeof json==='string')return json;
  if(Array.isArray(json))return json.find(v=>typeof v==='string'&&v.length>20)||'';
  for(const k of ['data','body','html','content','result','response','xml','text','fileContent']){
    const v=json&&json[k];
    if(typeof v==='string'&&v.length>20)return v;
    if(Array.isArray(v)){const s=v.find(x=>typeof x==='string'&&x.length>20);if(s)return s;}
  }
  for(const v of Object.values(json||{}))if(typeof v==='string'&&v.includes('<'))return v;
  return '';
}

const out=[];
for(const item of $input.all()){
  const xml=getContent(item.json);
  if(!xml) continue;
  for(const e of (xml.match(/<entry\b[\s\S]*?<\/entry>/g)||[])){
    const pick=re=>{const m=e.match(re);return m?m[1].trim():'';};
    const rawTitle=decodeEntities(pick(/<title>([\s\S]*?)<\/title>/));
    const link=pick(/<link\b[^>]*href="([^"]+)"/);
    const updated=pick(/<updated>([\s\S]*?)<\/updated>/);
    const idRaw=pick(/<id>([\s\S]*?)<\/id>/);
    const summary=decodeEntities(pick(/<summary[^>]*>([\s\S]*?)<\/summary>/)).replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
    const acc=(idRaw.match(/accession-number=([\w-]+)/)||[])[1]||(summary.match(/AccNo:\s*([\d-]+)/)||[])[1]||'';
    const filed=(summary.match(/Filed:\s*([\d-]{10})/)||[])[1]||'';
    const tm=rawTitle.match(/^(\S+)\s*-\s*(.+?)\s*\((\d{7,10})\)\s*\((\w+)\)\s*$/);
    const formType=tm?tm[1]:'', role=tm?tm[4]:'';
    if(formType!=='4') continue;
    if(role && role.toLowerCase()!=='reporting') continue;
    if(!acc) continue;
    out.push({ json: {
      filingId: 'EDGAR-'+acc,
      source: 'EDGAR',
      memberName: tm?tm[2]:rawTitle,
      party: '', state: '',
      transactionType: '', amountRange: '', transactionDate: '',
      filingDate: (filed||updated).slice(0,10),
      filingUrl: link||'https://www.sec.gov/cgi-bin/browse-edgar',
      cik: tm?tm[3]:''
    }});
  }
}
return out;

// Filter New Filings — dedup (vs sheet) + intra-run dedup + recency gate.
// Only filings filed within MAX_AGE_DAYS are alert-worthy. This prevents:
//   (1) first-run spam (sheet empty => everything looks "new"), and
//   (2) alerting on months-old filings that live in the House annual dump.
const MAX_AGE_DAYS = 20;                 // tune: 1-2 = very fresh only, 7 = looser
const now = Date.now();

let seen = new Set();
try {
  seen = new Set($('Read Seen Filings').all()
    .map(i => String((i.json['Filing ID'] ?? i.json.filingId ?? '')).trim())
    .filter(Boolean));
} catch (err) {}

const fresh = [];
const thisRun = new Set();
for (const item of $input.all()) {
  const j = item.json;
  const id = String(j.filingId || '').trim();
  if (!id || seen.has(id) || thisRun.has(id)) continue;

  // recency gate
  const fd = Date.parse(j.filingDate);
  if (!isNaN(fd) && (now - fd) > MAX_AGE_DAYS * 86400000) continue;

  thisRun.add(id);
  j.alertedAt = new Date().toISOString();
  fresh.push(item);
}
return fresh;
